 r.reaction(1,0,900);Bitmap a=Bitmap.createBitmap(240,520,Bitmap.Config.ARGB_8888),b=Bitmap.createBitmap(240,520,Bitmap.Config.ARGB_8888);r.draw(new Canvas(a),240,520,5,6,9000,2000000,false);r.reaction(1,0,1500);r.draw(new Canvas(b),240,520,5,6,9000,2000000,false);ok(!Arrays.equals(pixels(a),pixels(b)),"reaction age animates upper body");ok(Arrays.equals(Arrays.copyOfRange(pixels(a),300*240,240*520),Arrays.copyOfRange(pixels(b),300*240,240*520)),"reaction anchors hips knees feet");a.recycle();b.recycle();
 try(FileOutputStream file=new FileOutputStream(new File(c.getFilesDir(),"rest-content-v677-preview.png"))){sheet.compress(Bitmap.CompressFormat.PNG,100,file);}sheet.recycle();
 try(ZipOutputStream zip=new ZipOutputStream(new FileOutputStream(new File(c.getFilesDir(),"rest-content-v677-frames.zip")))){for(int step=0;step<21;step++){Bitmap frame=Bitmap.createBitmap(960,520,Bitmap.Config.ARGB_8888);Canvas cv=new Canvas(frame);cv.drawColor(Color.BLACK);for(int i=0;i<4;i++){cv.save();cv.translate(i*240,0);r.reaction(i+1,0,step*160);r.draw(cv,240,520,5,6+i,9000,3000000+step*160-400,false);r.draw(cv,240,520,5,6+i,9000,3000000+step*160,false);cv.restore();}zip.putNextEntry(new ZipEntry(String.format(java.util.Locale.ROOT,"frame-%03d.png",step)));frame.compress(Bitmap.CompressFormat.PNG,100,zip);zip.closeEntry();frame.recycle();}}
 body.endConversation();ok(reactions.kind(android.os.SystemClock.uptimeMillis())==0,"end clears pending reaction");body.releaseInspection();return n;
